-- Uses the modeled fixture and access checks from the reservation suite prefix.
create function pg_temp.result(command text,state text,refund text,receipt text,receipt_status text) returns text
language sql as $body$
 select platform_private.record_subscription_fiscal_result(md5(command)::uuid,md5('fiscal-payment')::uuid,'123',
 x.body_sha256,x.amount_minor,state,case when refund is null then null else md5(refund)::uuid end,receipt,receipt_status)
 from public.billing_subscription_fiscal_operations x where command_id=md5(command)::uuid;
$body$;
select platform_private.reserve_subscription_fiscal_operation(current_setting('test.payment')::uuid,md5('result-first')::uuid,0,'refund',1000);
select throws_ok($$select pg_temp.result('result-first','succeeded','refund-one',null,'unknown')$$,'55000','fiscal send not claimed','result cannot precede first send claim');
select is(platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)->>'action','send','first claim sends');
select set_config('test.first_sent',(select first_sent_at::text from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),true);
select is(platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)->>'action','reconcile','second claim never sends');
select is((select first_sent_at::text from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),current_setting('test.first_sent'),'first send time unchanged');
select is((select state from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),'unknown','crash after claim retains unknown');
select throws_ok($$select platform_private.record_subscription_fiscal_result(md5('result-first')::uuid,md5('wrong')::uuid,'123',(select body_sha256 from public.billing_subscription_fiscal_operations where command_id=md5('result-first')::uuid),1000,'succeeded',md5('refund-one')::uuid,null,'unknown')$$,'22023','fiscal result invalid','different payment rejected');
select throws_ok($$select platform_private.record_subscription_fiscal_result(md5('result-first')::uuid,md5('fiscal-payment')::uuid,'123','wrong-hash',1000,'succeeded',md5('refund-one')::uuid,null,'unknown')$$,'22023','fiscal result invalid','different snapshot rejected');
select throws_ok($$select pg_temp.result('result-first','succeeded',null,null,'unknown')$$,'22023','fiscal result invalid','refund identity required');
savepoint expired;
update public.billing_subscription_fiscal_operation_status set first_sent_at=clock_timestamp()-interval '25 hours' where command_id=md5('result-first')::uuid;
select is(platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)->>'action','review','old unidentified attempt cannot send again');
select ok((select requires_review from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),'expired unknown is sticky review');
rollback to expired;
select is(pg_temp.result('result-first','pending','refund-one',null,null),'pending','pending identity saved');
savepoint known;
update public.billing_subscription_fiscal_operation_status set first_sent_at=clock_timestamp()-interval '25 hours' where command_id=md5('result-first')::uuid;
select is(platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)->>'action','reconcile','known refund remains readable after idempotency window');
rollback to known;
select is(pg_temp.result('result-first','succeeded','refund-one',null,'unknown'),'succeeded','money success saved without receipt success');
select throws_ok($$select platform_private.reserve_subscription_fiscal_operation(current_setting('test.payment')::uuid,md5('too-early')::uuid,1,'settlement',5172)$$,'55000','fiscal operation unresolved','unknown receipt retains block');
select is(pg_temp.result('result-first','pending','refund-one',null,null),'succeeded','late pending cannot reverse monetary success');
select is(pg_temp.result('result-first','succeeded','refund-one','ra-11111111-1111-4111-8111-111111111111','succeeded'),'succeeded','ra receipt confirmed');
select is(pg_temp.result('result-first','succeeded','refund-one',null,'unknown'),'succeeded','late unknown cannot reverse receipt success');
select is((select receipt_status from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),'succeeded','receipt success retained');
savepoint conflict;
select is(pg_temp.result('result-first','canceled','refund-one',null,null),'review','contradictory terminal money state requires review');
select is((select state from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),'succeeded','contradiction preserves terminal value');
select throws_ok($$select platform_private.reserve_subscription_fiscal_operation(current_setting('test.payment')::uuid,md5('review-block')::uuid,1,'refund',1000)$$,'55000','fiscal review required','review blocks new reserve even after success');
select is(platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)->>'action','review','review blocks dispatch');
select is(pg_temp.result('result-first','succeeded','refund-one',null,'unknown'),'review','normal reply cannot clear review');
rollback to conflict;
savepoint wrongid;
select is(pg_temp.result('result-first','succeeded','refund-other','ra-11111111-1111-4111-8111-111111111111','succeeded'),'review','different refund id quarantined');
select is((select provider_refund_id from public.billing_subscription_fiscal_operation_status where command_id=md5('result-first')::uuid),md5('refund-one')::uuid,'original refund identity preserved');
rollback to wrongid;
savepoint wrongreceipt;
select is(pg_temp.result('result-first','succeeded','refund-one','rt-22222222-2222-4222-8222-222222222222','succeeded'),'review','different receipt id quarantined');
rollback to wrongreceipt;
select platform_private.reserve_subscription_fiscal_operation(current_setting('test.payment')::uuid,md5('result-settle')::uuid,1,'settlement',5172);
select is(platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)->>'action','send','settlement claimed once');
select is(pg_temp.result('result-settle','pending',null,'rt-22222222-2222-4222-8222-222222222222',null),'pending','rt settlement identity saved');
savepoint canceled_settlement;
select is(pg_temp.result('result-settle','canceled',null,'rt-22222222-2222-4222-8222-222222222222',null),'review','canceled settlement requires review');
select is(platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)->>'action','review','canceled settlement cannot dispatch');
rollback to canceled_settlement;
select is(pg_temp.result('result-settle','succeeded',null,'rt-22222222-2222-4222-8222-222222222222','succeeded'),'succeeded','settlement confirmed through result function');
select platform_private.reserve_subscription_fiscal_operation(current_setting('test.payment')::uuid,md5('result-last')::uuid,2,'refund',5172);
savepoint late_conflict;
select pg_temp.result('result-first','canceled','refund-one',null,null);
select is(platform_private.claim_subscription_fiscal_operation(md5('result-last')::uuid)->>'action','review','late conflict on earlier command blocks reserved successor');
select ok((select first_sent_at is null from public.billing_subscription_fiscal_operation_status where command_id=md5('result-last')::uuid),'blocked successor has no send claim');
rollback to late_conflict;
select platform_private.claim_subscription_fiscal_operation(md5('result-last')::uuid);
savepoint duplicate;
select is(pg_temp.result('result-last','succeeded','refund-one',null,'unknown'),'review','provider refund ID cannot belong to two commands');
select is((select state from public.billing_subscription_fiscal_operation_status where command_id=md5('result-last')::uuid),'unknown','identity collision does not apply monetary success');
rollback to duplicate;
savepoint duplicate_receipt;
select is(pg_temp.result('result-last','succeeded','refund-two','ra-11111111-1111-4111-8111-111111111111','succeeded'),'review','receipt ID cannot belong to two commands');
rollback to duplicate_receipt;
savepoint receipt_canceled;
select is(pg_temp.result('result-last','succeeded','refund-two','ra-33333333-3333-4333-8333-333333333333','canceled'),'review','canceled refund receipt requires review');
select is((select state from public.billing_subscription_fiscal_operation_status where command_id=md5('result-last')::uuid),'succeeded','canceled receipt does not undo refunded money');
rollback to receipt_canceled;
select is(pg_temp.result('result-last','succeeded','refund-two','ra-33333333-3333-4333-8333-333333333333','succeeded'),'succeeded','final refund and receipt confirmed');
select is((select sum(x.amount_minor) from public.billing_subscription_fiscal_operations x join public.billing_subscription_fiscal_operation_status s using(command_id) where x.kind<>'settlement' and s.state='succeeded'),6172::numeric,'lifecycle chain fully refunded');
set local role authenticated;
select throws_ok($$select platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)$$,'42501',null,'browser claim denied');
select throws_ok($$select platform_private.record_subscription_fiscal_result(null,null,null,null,null,null,null,null,null)$$,'42501',null,'browser result forgery denied');
reset role;
set local role service_role;
select throws_ok($$select platform_private.claim_subscription_fiscal_operation(md5('result-first')::uuid)$$,'42501',null,'unintegrated service claim denied');
select throws_ok($$select platform_private.record_subscription_fiscal_result(null,null,null,null,null,null,null,null,null)$$,'42501',null,'unintegrated service result denied');
reset role;
savepoint adapter_review;
select lives_ok($$select platform_private.mark_subscription_fiscal_review(md5('result-last')::uuid,'provider_mismatch')$$,'adapter can persist verified mismatch internally');
select is(platform_private.claim_subscription_fiscal_operation(md5('result-last')::uuid)->>'action','review','adapter mismatch prevents further processing');
select throws_ok($$select platform_private.mark_subscription_fiscal_review(md5('result-last')::uuid,'private raw response')$$,'22023','invalid fiscal review reason','raw provider text cannot be review reason');
set local role service_role;
select throws_ok($$select platform_private.mark_subscription_fiscal_review(md5('result-last')::uuid,'provider_mismatch')$$,'42501',null,'unintegrated service review denied');
reset role;
rollback to adapter_review;
select is(platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)->>'expectedRefundedMinor','1000','claim retains balance before its own operation');
select is(jsonb_array_length(platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)->'priorReceipts'),1,'claim includes exact predecessor receipt list');
select is(platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)#>>'{priorReceipts,0,id}','ra-11111111-1111-4111-8111-111111111111','claim pins prior receipt identity');
select ok(not((platform_private.claim_subscription_fiscal_operation(md5('result-settle')::uuid)->'priorReceipts')::text like '%@%'),'predecessor summaries exclude buyer contact');
